3.3.4 基座的脚本示例

基座提供了一个 Player 脚本作为写脚本的标准范式，AI 能直观理解脚本的写法：

```
// src/scripts/player.ts —— 基座中的示范脚本import { ConfigurableScript } from '@/scene/script-runtime' 
type PlayerScriptConfig = {  swingSpeed?: number        // scene.json 中注入的配置参数  pulseSpeed?: number  rotationAmplitude?: number  scaleAmplitude?: number} 
export class Player extends ConfigurableScript<PlayerScriptConfig> {  private elapsed = 0 
  onAwake(): void {    // 记录初始缩放，后续动画基于此计算    this.baseScaleX = this.entity.transform.scale.x  } 
  onUpdate(deltaTime: number): void {    this.elapsed += deltaTime    // 从 scene.json 的 scriptIds[].config 中读取参数    const swingSpeed = this.scriptConfig.swingSpeed ?? 2.2    // 从外部数据源读取运行时参数    const scaleMultiplier = this.externalValue?.scaleMultiplier ?? 1 
    // 摆动 + 脉动动画    const swing = Math.sin(this.elapsed * swingSpeed)    const scale = 1 + Math.sin(this.elapsed * this.scriptConfig.pulseSpeed) * scaleAmplitude 
    this.entity.transform.rotation.set(0, 0, swing * rotationAmplitude)    this.entity.transform.scale.set(baseX * scale, baseY * scale, 1)  }}
```
